ion']??''))?></textarea></label><?php if($errors):?><div class="alert alert-error">Formdaki bilgileri kontrol et.</div><?php endif;?><button class="btn btn-primary">Rakip İlanını Yayınla</button></form></section></main><?php require __DIR__.'/../layouts/footer.php'; ?>
